import json

def total_qty(text):
    return sum(it['qty'] for it in json.loads(text)['items'])

assert total_qty('{"items":[{"name":"a","qty":2},{"name":"b","qty":5}],"v":1}') == 7
assert total_qty('{"items":[]}') == 0

